/* Shared single-project detail shell, backed by the current workspace records. */
window.ProjectDetail=(()=>{
 function render(data,{active='overview',avatar,date,today}){
  const {project:p,members,teams,issues,documents,notes}=data;
  const tasks=issues.filter(t=>t.projectId===p.id),done=tasks.filter(t=>t.status==='Done').length,team=teams.find(t=>t.id===p.teamId);
  const ids=new Set([p.managerId,...(p.memberIds||[]),...(team?.memberIds||[]),...tasks.map(t=>t.assigneeId)].filter(Boolean)),people=members.filter(m=>ids.has(m.id));
  const files=documents.filter(d=>d.projectId===p.id&&!d.trashed),projectNotes=notes.filter(n=>n.projectId===p.id),progress=Planning.progress(tasks);
  const remaining=Planning.day(p.endDate)-Planning.day(today),duration=Planning.day(p.endDate)-Planning.day(p.startDate)+1;
  return `<div class="project-detail ${active==='charter'?'detail-charter':''}"><div class="detail-breadcrumb"><button class="text-btn" data-all-projects>Projects</button><span>›</span><label class="sr-only" for="dashboard-project">Current project</label><select id="dashboard-project">${data.projects.map(x=>`<option value="${esc(x.id)}" ${x.id===p.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><button class="secondary" data-refresh-project>Refresh</button><button class="primary" data-project-new-task="${esc(p.id)}">+ Task</button></div><div class="detail-layout"><div class="detail-main"><div class="detail-header"><div class="detail-title"><h1>${esc(p.name)}</h1><span class="badge">${esc(p.status)}</span></div><div class="detail-meta"><span>Code <b>${esc(ProjectAPI.projectKey(p))}</b></span><span>${people.length} contributors</span><span>${esc(team?.name||'No team assigned')}</span></div></div><div class="detail-stats"><div><span>Task completion</span><strong>${progress}%</strong><div class="progress-track"><i style="width:${progress}%"></i></div></div><div><span>Due date</span><strong>${date(p.endDate)}</strong><small>${p.status==='Completed'?'Project completed':remaining<0?Math.abs(remaining)+' days past due':remaining+' days left'}</small></div><div><span>Tasks closed</span><strong>${done}<small> / ${tasks.length}</small></strong><small>${tasks.length-done} open tasks</small></div><div><span>Project documents</span><strong>${files.length}</strong><small>Files and notes</small></div></div><section class="detail-brief"><h2>Project brief</h2><p>${esc(p.description||'Add a project description to share its purpose and scope.')}</p></section><section class="detail-files"><div><h2>Project files</h2><button class="text-btn" data-project-docs="${esc(p.id)}">Manage documents</button></div><div class="detail-file-grid">${files.slice(0,3).map(d=>`<button data-doc-open="${esc(d.id)}"><span class="detail-file-icon">${d.kind==='file'?'▤':'≡'}</span><span><strong>${esc(d.name)}</strong><small>${esc(d.category||'Document')}</small></span><span>↗</span></button>`).join('')||'<p class="muted">No project files yet.</p>'}</div></section><div id="project-tab-panel" role="region" aria-label="${esc(ProjectTools.titles[active]||active)}"></div></div><div class="detail-sidebar" role="complementary" aria-label="Project details"><section><h2>Project status</h2><dl><div><dt>Status</dt><dd><span class="badge">${esc(p.status)}</span></dd></div><div><dt>Team</dt><dd>${esc(team?.name||'Unassigned')}</dd></div><div><dt>Manager</dt><dd>${avatar(members.find(m=>m.id===p.managerId))}<span>${esc(members.find(m=>m.id===p.managerId)?.name||'Unassigned')}</span></dd></div></dl><button class="text-btn" data-project-edit="${esc(p.id)}">Edit project</button></section><section><h2>Contributors <small>${people.length}</small></h2><div class="detail-contributors">${people.map(avatar).join('')||'<p class="muted">No members yet.</p>'}</div></section><section><h2>Schedule</h2><dl><div><dt>Start date</dt><dd>${date(p.startDate)}</dd></div><div><dt>Due date</dt><dd>${date(p.endDate)}</dd></div><div><dt>Duration</dt><dd>${duration} days</dd></div></dl></section><section><h2>Notes</h2>${projectNotes.slice(0,3).map(n=>`<button class="detail-note" data-note-edit="${esc(n.id)}"><strong>${esc(n.name)}</strong><p>${esc(n.content||'')}</p></button>`).join('')||'<p class="muted">No project notes yet.</p>'}</section></div></div></div>`;
 }
 return {render};
})();
